void str_copy_no_nul(char *dst, char *src, int n)
{
  char c;

  if (*src != '\0' && n != 0) {
    do {
      c = *src;
      src = src + 1;
      *dst = c;
      dst = dst + 1;
      n = n + -1;
    } while (*src != '\0' && n != 0);
  }
  return;
}

